// Independent auditor PLAY-02 real-engine privacy probe.
// Part A: real synthetic-engine states, re-labelled with a unique definition per instance so hidden
// identities are heterogeneous, then paired worlds that differ only in what a viewer may not know.
// Part B: the private match API driven entirely through viewer references (the PLAY-03 path).
import assert from 'node:assert/strict';
import { randomBytes, createHash } from 'node:crypto';
import { createSyntheticKernel } from './vendor/tcg-engines/dist/kernel.js';
import { createRandomSource } from './packages/engine-adapter/dist/random.js';
import { createViewerProjection } from './packages/engine-adapter/dist/viewer.js';
import { encodeViewerProjection, encodeViewerSurface, decodeViewerSurface } from './packages/contracts/dist/index.js';
import { createPrivateMatch, restorePrivateMatch } from './packages/engine-adapter/dist/index.js';
import { isPlayerMove } from './packages/contracts/dist/player-moves.js';

const players = ['p1', 'p2'], other = p => players.find(x => x !== p);
const viewers = [{ kind: 'participant', playerId: 'p1' }, { kind: 'participant', playerId: 'p2' }, { kind: 'public' }];
const label = v => v.kind === 'public' ? 'public' : v.playerId;
const surfaces = ['snapshot', 'resources', 'logs', 'animations', 'export'];
let lcg = 20261014;
const rand = n => { lcg = (lcg * 1103515245 + 12345) % 2 ** 31; return lcg % n; };
const shuffle = a => { for (let i = a.length - 1; i > 0; i--) { const j = rand(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; };
const bytesOf = (src, viewer, key) => { const p = createViewerProjection(src, { matchId: 'audit-match', viewer, key }); return [encodeViewerProjection(p.snapshot), ...surfaces.map(s => encodeViewerSurface(p.snapshot, s))].join('\n'); };
const visibleTo = (viewer, vt) => vt === 'all' || (viewer.kind === 'participant' && Array.isArray(vt) && vt.includes(viewer.playerId));

// What the viewer is entitled to know, derived from the rules policy rather than the projector code.
function knowledge(src, viewer) {
  const zones = src.state.ctx.zones.private.zoneCards, meta = src.state.ctx.zones.private.cardMeta, revealed = new Set(), hidden = new Set(), shown = new Set(), hiddenByZone = {};
  for (const e of src.events) if (e.event.kind === 'REVEAL_CREATED' && visibleTo(viewer, e.event.visibleTo)) for (const c of e.event.cardIds) revealed.add(c);
  for (const r of src.state.ctx.zones.reveals.active) if (visibleTo(viewer, r.visibleTo)) for (const c of r.cardIDs) revealed.add(c);
  for (const p of players) for (const kind of ['hand', 'deck', 'play', 'discard', 'inkwell']) for (const c of zones[kind + ':' + p]) {
    const m = meta[c] ?? {};
    const publicFront = (kind === 'play' && m.publicFaceState !== 'faceDown' && (!m.stackParentId || m.publicFaceState === 'faceUp')) || (kind === 'discard' && m.publicFaceState !== 'faceDown');
    const own = kind === 'hand' && viewer.kind === 'participant' && viewer.playerId === p;
    if (publicFront || own || revealed.has(c)) shown.add(c); else { hidden.add(c); (hiddenByZone[kind + ':' + p] ??= []).push(c); }
  }
  return { hidden, shown, revealed, hiddenByZone };
}
function perturb(src, viewer) {
  const { hidden } = knowledge(src, viewer);
  let json = JSON.stringify(src);
  const renamed = [];
  for (const c of hidden) { const next = 'instance-' + randomBytes(32).toString('hex'); json = json.split(c).join(next); renamed.push(next); }
  const out = JSON.parse(json), zones = out.state.ctx.zones.private.zoneCards, meta = out.state.ctx.zones.private.cardMeta, index = out.state.ctx.zones.private.cardIndex;
  for (const c of renamed) out.instances[c] = 'hidden-def-' + rand(1e9);
  for (const p of players) for (const kind of ['hand', 'deck', 'inkwell']) {
    shuffle(zones[kind + ':' + p]);
    for (const c of zones[kind + ':' + p]) {
      const m = meta[c] ??= {}; m.damage = 7; m.isDrying = true; if (kind !== 'inkwell') m.state = 'exerted'; // inkwell orientation is public
      if (index[c]) index[c].controllerID = other(index[c].ownerID);
    }
  }
  out.state.G.auditPrivate = randomBytes(8).toString('hex'); out.state.ctx.auditPrivate = rand(1e9);
  for (const e of out.events) if (e.event.input) e.event.input.auditNoise = rand(1e9);
  return out;
}
function relabel(src) { // unique definition per private instance makes hidden identity meaningful
  for (const id of Object.keys(src.instances)) src.instances[id] = 'def-' + createHash('sha256').update(id).digest('hex').slice(0, 12);
  return src;
}

// ---------- Part A ----------
const seed = randomBytes(32), key = randomBytes(32);
const kernel = createSyntheticKernel({ randomSource: createRandomSource(seed, 'audit-play02'), players, startTimestamp: 1000 });
let ts = 1000, n = 0;
const A = { states: 0, comparisons: 0, positives: 0, hiddenMax: 0, oppHandHidden: 0, ownDeckHidden: 0, inkReveals: 0, refs: new Set(), accepted: 0 };
function checkState() {
  A.states++;
  const secrets = new Set();
  for (const v of viewers) {
    const src = relabel(kernel.inspect(v.kind === 'participant' ? v.playerId : undefined));
    for (const m of JSON.stringify(src).matchAll(/[a-f0-9]{64}/g)) secrets.add(m[0]);
    secrets.add(seed.toString('hex')); secrets.add(key.toString('hex'));
    const base = bytesOf(src, v, key);
    for (const s of secrets) assert.equal(base.includes(s), false, 'private identity in output for ' + label(v));
    assert.equal(/instance-|"seed"|randomOutcomes|cardMeta|zoneCards|"G"|"ctx"/.test(base), false, 'raw engine material in output');
    for (let i = 0; i < 3; i++) { assert.equal(bytesOf(perturb(src, v), v, key), base, 'hidden-world difference visible to ' + label(v) + ' at revision ' + kernel.status().revision); A.comparisons++; }
    const k = knowledge(src, v), snap = createViewerProjection(src, { matchId: 'audit-match', viewer: v, key }).snapshot;
    A.hiddenMax = Math.max(A.hiddenMax, k.hidden.size);
    if (v.kind === 'participant') {
      if ((k.hiddenByZone['hand:' + other(v.playerId)] ?? []).length) A.oppHandHidden++;
      if ((k.hiddenByZone['deck:' + v.playerId] ?? []).length) A.ownDeckHidden++;
      assert.deepEqual(snap.commands.filter(x => !isPlayerMove(x)), []);
    } else assert.deepEqual(snap.commands, []);
    for (const ref of JSON.stringify(snap).match(/vr_[a-f0-9]{64}/g) ?? []) { assert.equal(A.refs.has(ref + label(v)), false, 'ref repeated'); A.refs.add(ref + label(v)); }
    for (const p of snap.players) for (const z of p.zones) {
      if (z.kind === 'inkwell') for (const c of z.cards) assert.equal('definitionId' in c, false, 'ink front exposed');
      if (z.kind === 'deck') assert.equal(z.cards.length, 0, 'deck card exposed without reveal');
      if (z.kind === 'hand' && !(v.kind === 'participant' && v.playerId === p.playerId)) assert.equal(z.cards.length, 0, 'other hand exposed');
    }
    // Positive (non-vacuity) controls: entitled knowledge must actually change the bytes.
    const zones = src.state.ctx.zones.private.zoneCards, flip = (id) => { const c = structuredClone(src); c.instances[id] = 'changed-def'; return bytesOf(c, v, key); };
    if (v.kind === 'participant' && zones['hand:' + v.playerId].length) { assert.notEqual(flip(zones['hand:' + v.playerId][0]), base, 'own hand not shown'); A.positives++; }
    const inPlay = players.flatMap(p => zones['play:' + p]);
    if (inPlay.length) { assert.notEqual(flip(inPlay[0]), base, 'play card not shown'); A.positives++; }
    const inked = src.events.filter(e => e.event.kind === 'MOVE_EXECUTED' && e.event.move === 'putCardIntoInkwell').map(e => e.event.input.args.cardId);
    if (inked.length) { assert.notEqual(flip(inked[0]), base, 'public inking history missing'); A.positives++; A.inkReveals = Math.max(A.inkReveals, inked.length); }
  }
}
const submit = (actor, move, input) => { const r = kernel.submit(actor, kernel.status().revision, ts += 10, 'a' + (n++), move, input); if (r.accepted) { A.accepted++; checkState(); } return r.accepted; };
let chosenA = false;
checkState();
for (let guard = 0; guard < 120 && !kernel.status().ended; guard++) {
  const s = kernel.status();
  if (!chosenA) { assert(submit(s.choosingFirstPlayer, 'chooseWhoGoesFirst', { playerId: 'p1' })); chosenA = true; continue; } // status keeps the chooser after the choice
  const st = kernel.inspect().state, zones = st.ctx.zones.private.zoneCards;
  const mull = players.find(p => kernel.inspect(p).moves.includes('alterHand'));
  if (mull) { assert(submit(mull, 'alterHand', { cardsToMulligan: mull === 'p1' ? zones['hand:p1'].slice(0, 2) : [] })); continue; }
  const actor = st.ctx.status.turnOwnerId; assert(players.includes(actor));
  for (const c of [...zones['hand:' + actor]]) if (submit(actor, 'putCardIntoInkwell', { cardId: c })) break;
  for (const c of [...kernel.inspect().state.ctx.zones.private.zoneCards['hand:' + actor]]) submit(actor, 'playCard', { cardId: c, cost: 'standard' });
  const now = () => kernel.inspect().state.ctx.zones.private.zoneCards;
  for (const att of [...now()['play:' + actor]]) for (const def of [...now()['play:' + other(actor)]]) if (submit(actor, 'challenge', { attackerId: att, defenderId: def })) break;
  for (const c of [...now()['play:' + actor]]) submit(actor, 'quest', { cardId: c });
  if (!kernel.status().ended) assert(submit(actor, 'passTurn', {}), 'passTurn refused');
}
const endA = kernel.status();
assert(A.oppHandHidden > 0 && A.ownDeckHidden > 0 && A.positives > 0 && A.inkReveals > 0, 'probe would be vacuous');

// ---------- Part B ----------
const setup = { matchId: 'audit-refs', players, startTimestamp: 100 };
const m = createPrivateMatch(setup);
const B = { revisions: 0, staleRejected: 0, crossRejected: 0, publicRejected: 0, rawRejected: 0, restores: 0, readOnly: 0, refs: new Set(), backResolves: 0, backCodes: new Set(), accepted: 0, moves: new Set() };
let bt = 100, bn = 0, previous = [];
const views = () => Object.fromEntries(viewers.map(v => [label(v), m.project(v)]));
const refsIn = view => JSON.stringify(view).match(/vr_[a-f0-9]{64}/g) ?? [];
const rejects = (actor, ref) => assert.throws(() => m.resolveIntent(actor, 'quest', { cardId: ref }), /Reference rejected/);
function checkRevision() {
  B.revisions++;
  const cp = m.checkpoint(), archive = JSON.parse(cp.archive), current = views();
  const secrets = [archive.transcript.seed, cp.digest, m.status().seedCommitment, ...archive.transcript.initial.randomOutcomes.filter(o => String(o.kind).startsWith('identifier')).map(o => String(o.value))].filter(Boolean);
  assert(secrets.length > 20, 'secret list unexpectedly small');
  for (const [name, view] of Object.entries(current)) {
    const raw = [encodeViewerProjection(view), ...surfaces.map(s => encodeViewerSurface(view, s))].join('\n');
    for (const s of secrets) assert.equal(raw.includes(s), false, 'secret in ' + name + ' view');
    for (const s of surfaces) assert.equal(decodeViewerSurface(encodeViewerSurface(view, s)).surface, s);
    for (const ref of refsIn(view)) { assert.equal(B.refs.has(ref), false, 'reference reused across viewer/revision'); B.refs.add(ref); }
  }
  for (const v of viewers) m.project(v), m.project(v);
  assert.deepEqual(m.checkpoint(), cp, 'projection changed state or consumed randomness'); B.readOnly++;
  const restored = restorePrivateMatch(cp, setup.matchId);
  try { for (const v of viewers) assert.deepEqual(restored.project(v), current[label(v)], 'recovery changed projection'); B.restores++; } finally { restored.dispose(); }
  for (const ref of previous) for (const p of players) { rejects(p, ref); B.staleRejected++; }
  for (const p of players) {
    for (const ref of refsIn(current[other(p)])) { rejects(p, ref); B.crossRejected++; }
    for (const ref of refsIn(current.public)) { rejects(p, ref); B.publicRejected++; }
    for (const ref of refsIn(current[p]).slice(0, 4)) {
      const internal = m.resolveIntent(p, 'quest', { cardId: ref }).cardId;
      assert.match(internal, /^instance-[a-f0-9]{64}$/);
      assert.throws(() => m.resolveIntent(p, 'quest', { cardId: internal }), /Reference rejected/); B.rawRejected++;
    }
  }
  previous = Object.values(current).flatMap(refsIn);
}
const bsubmit = (actor, move, input) => {
  let resolved; try { resolved = m.resolveIntent(actor, move, input); } catch { return false; }
  const r = m.submit({ actor, move, input: resolved, commandId: 'b' + (bn++), expectedRevision: m.status().revision, timestamp: bt += 1 });
  if (r.accepted) { B.accepted++; B.moves.add(move); checkRevision(); }
  return r.accepted;
};
const zone = (view, p, kind) => view.players.find(x => x.playerId === p).zones.find(z => z.kind === kind);
let chosenB = false;
checkRevision();
for (let guard = 0; guard < 120 && !m.status().ended; guard++) {
  const s = m.status();
  if (!chosenB) { assert(bsubmit(s.choosingFirstPlayer, 'chooseWhoGoesFirst', { playerId: 'p1' })); chosenB = true; continue; }
  const mull = players.find(p => m.project({ kind: 'participant', playerId: p }).commands.includes('alterHand'));
  if (mull) { const hand = zone(m.project({ kind: 'participant', playerId: mull }), mull, 'hand').cards.map(c => c.ref); assert(bsubmit(mull, 'alterHand', { cardsToMulligan: mull === 'p1' ? hand.slice(0, 2) : [] })); continue; }
  const actor = m.project({ kind: 'public' }).turnOwnerId, me = () => m.project({ kind: 'participant', playerId: actor });
  // Informational: references to the opponent's anonymous ink backs resolve server-side; record engine outcome.
  for (const back of zone(me(), other(actor), 'inkwell').cards.slice(0, 1)) {
    const att = zone(me(), actor, 'play').cards[0];
    if (att) { try { const input = m.resolveIntent(actor, 'challenge', { attackerId: att.ref, defenderId: back.ref }); B.backResolves++; B.backCodes.add(m.submit({ actor, move: 'challenge', input, commandId: 'probe' + (bn++), expectedRevision: m.status().revision, timestamp: bt }).code); } catch { B.backCodes.add('resolver-refused'); } }
  }
  for (const c of zone(me(), actor, 'hand').cards) if (bsubmit(actor, 'putCardIntoInkwell', { cardId: c.ref })) break;
  for (let again = true; again;) { again = false; for (const c of zone(me(), actor, 'hand').cards) if (bsubmit(actor, 'playCard', { cardId: c.ref, cost: 'standard' })) { again = true; break; } }
  for (let again = true; again;) { again = false; for (const att of zone(me(), actor, 'play').cards) { for (const def of zone(me(), other(actor), 'play').cards) if (bsubmit(actor, 'challenge', { attackerId: att.ref, defenderId: def.ref })) { again = true; break; } if (again) break; } }
  for (let again = true; again;) { again = false; for (const c of zone(me(), actor, 'play').cards) if (bsubmit(actor, 'quest', { cardId: c.ref })) { again = true; break; } }
  if (!m.status().ended) assert(bsubmit(actor, 'passTurn', {}), 'passTurn refused');
}
const endB = m.status(); m.dispose();
assert(B.staleRejected > 100 && B.crossRejected > 100 && B.rawRejected > 20 && B.moves.has('challenge') && B.moves.has('quest') && B.moves.has('playCard') && B.moves.has('putCardIntoInkwell'), 'reference probe too narrow');
console.log(JSON.stringify({ partA: { ...A, refs: A.refs.size, ended: endA.ended, winner: endA.winner, finalRevision: endA.revision }, partB: { ...B, refs: B.refs.size, backCodes: [...B.backCodes], moves: [...B.moves], ended: endB.ended, winner: endB.winner, finalRevision: endB.revision } }));
console.log('PASS auditor PLAY-02 real-engine probe: at every revision of a complete synthetic game, three viewers x three paired hidden worlds (renamed/reshuffled hidden instances, unique hidden definitions, hidden metadata/controller, raw G/ctx/event noise) give byte-identical snapshot and surface encodings, while own hand, play and public inking history change the bytes; no 64-hex engine identity, seed or key appears; reference-driven play of ink/play/challenge/quest/pass is read-only for projections, reproduced after restore, rotates every revision and rejects stale, cross-viewer, public and raw identities');
